// Checkout conversion module - ensures paidEvents increment on successful checkout
const { logRevenueEvent } = require('./revenue-tracker');

module.exports = function checkoutConversion(req, res, next) {
  // Intercept checkout completion
  const originalJson = res.json.bind(res);
  res.json = function (body) {
    if (res.statusCode === 200 && body && body.success) {
      // Log paid event
      logRevenueEvent({
        type: 'paid',
        amount: body.amount || 0,
        currency: 'USD',
        timestamp: new Date().toISOString()
      });
    }
    return originalJson(body);
  };
  next();
};
